      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-wsl-port\",\n  \"version\": \"0.2.2\",\n  \"description\": \"WSL port doctor; dsh ≥0.1.2 uiPlaybook uses :3081/?token= (bare :3081 is 401).\",\n  \"license\": \"MIT\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"https://github.com/173787247/dsh-wsl-port.git\"\n  },\n  \"bugs\": {\n    \"url\": \"https://github.com/173787247/dsh-wsl-port/issues\"\n  },\n  \"homepage\": \"https://github.com/173787247/dsh-wsl-port#readme\",\n  \"type\": \"module\",\n  \"main\": \"index.js\",\n  \"engines\": { \"node\": \">=18\" },\n  \"scripts\": { \"test\": \"node --test test/port.test.js\" },\n  \"files\": [\"index.js\", \"lib\", \"cordis.patch.yml\", \"README.md\", \"README.zh.md\", \"LICENSE\",\n    \"CHANGELOG.md\",\n    \"CONTRIBUTING.md\"],\n  \"keywords\": [\"dsh-plugin\", \"deepseek-harness\", \"wsl\", \"port\"],\n  \"dsh\": { \"bundle\": { \"patch\": \"./cordis.patch.yml\" } }\n}\n"
    },
